// 1. Prepare for Name Resolution - v1.11 (Fixed zkb_hash extraction)

const items = $input.all();
const allUniqueIds = new Set();
const killmailIdToDataMap = new Map();

for (const item of items) {
    const km = item.json;
    let hash = null;

    // Method 1: Check pairedItem path
    if (item.pairedItem?.json?.package?.zkb?.hash) {
        hash = item.pairedItem.json.package.zkb.hash;
    }

    // Method 2: Check if hash is already in km.package
    if (!hash && km?.package?.zkb?.hash) {
        hash = km.package.zkb.hash;
    }

    // Method 3: Check if zkb_hash already exists at top level
    if (!hash && km?.zkb_hash) {
        hash = km.zkb_hash;
    }

    if (!km || !km.killmail_id) {
        continue;
    }

    // Store killmail with hash at top level
    const dataToStore = { ...km, zkb_hash: hash };
    killmailIdToDataMap.set(km.killmail_id, dataToStore);

    const addId = (id) => {
        if (typeof id === 'number' && id > 0) {
            allUniqueIds.add(id);
        }
    };

    addId(km.solar_system_id);

    if (km.victim) {
        addId(km.victim.character_id);
        addId(km.victim.corporation_id);
        addId(km.victim.alliance_id);
        addId(km.victim.ship_type_id);
        addId(km.victim.faction_id);
    }

    if (Array.isArray(km.attackers)) {
        for (const attacker of km.attackers) {
            addId(attacker.character_id);
            addId(attacker.corporation_id);
            addId(attacker.alliance_id);
            addId(attacker.faction_id);
            addId(attacker.ship_type_id);
            addId(attacker.weapon_type_id);
        }
    }

    if (km.victim?.items && Array.isArray(km.victim.items)) {
        for (const item of km.victim.items) {
            addId(item.item_type_id);
        }
    }
}

const all_ids_to_resolve = [...allUniqueIds];

const outputData = {
    killmail_id_map: Object.fromEntries(killmailIdToDataMap),
    all_ids_to_resolve: all_ids_to_resolve
};

console.log(`Extracted ${all_ids_to_resolve.length} valid unique IDs for resolution.`);
console.log(`Passing through ${killmailIdToDataMap.size} raw killmails for processing.`);

return [{ json: outputData }];

// Node 2: Check Redis Cache (v1.4 - Full Restore + Retry Logic)
const Redis = require('ioredis');
let redis;

try {
	// --- Initialization ---
	redis = new Redis({ host: 'redis', port: 6379, db: 0, connectTimeout: 5000 });

	await new Promise((resolve, reject) => {
		redis.on('ready', resolve);
		redis.on('error', (err) => {
			console.error('[Check Cache] Initial Redis connection error:', err);
			reject(err);
		});
	});

	console.log('[Check Cache] Connected to Redis successfully.');

	const inputData = $input.first().json;
	const idsToCheck = inputData.all_ids_to_resolve || [];

	// Constants for Hash Keys
	const ID_TO_NAME_HASH_KEY = 'eve:id_to_name';
	const NAME_TO_ID_HASH_KEY = 'eve:name_to_id';

	const cachedNames = {}; // Map of { id: Name } for found names
	const missingIds = [];  // List of IDs to send to ESI resolution
	const RETRY_COOLDOWN = 1000 * 60 * 60 * 4; // 4 Hour Negative Cache Cooldown

	if (idsToCheck.length > 0) {
		console.log(`[Check Cache] Validating ${idsToCheck.length} unique IDs against Redis...`);

		// --- Step 1: Bulk Check Existence in Hash ---
		const existsPipeline = redis.pipeline();
		idsToCheck.forEach(id => {
			if (id) {
				existsPipeline.hexists(ID_TO_NAME_HASH_KEY, String(id));
			} else {
				console.warn('[Check Cache] Encountered null/undefined ID in resolution list.');
			}
		});

		const existsResults = await existsPipeline.exec();

		const existingIds = []; 
		const existingStringIds = []; 

		for (let i = 0; i < idsToCheck.length; i++) {
			const id = idsToCheck[i];
			// Check Redis result: index [i], error [0], result [1] (1 = exists)
			if (id && existsResults && existsResults[i] && !existsResults[i][0] && existsResults[i][1] === 1) {
				existingIds.push(id);
				existingStringIds.push(String(id));
			} else if (id) {
				missingIds.push(id);
			}
		}

		console.log(`[Check Cache] Results: ${existingIds.length} found in cache, ${missingIds.length} identified as missing.`);

		// --- Step 2: Fetch names and evaluate Retry Cooldown ---
		if (existingStringIds.length > 0) {
			console.log(`[Check Cache] Fetching name strings for ${existingStringIds.length} existing IDs...`);

			const nameResults = await redis.hmget(ID_TO_NAME_HASH_KEY, ...existingStringIds);
			const nameToIdPipeline = redis.pipeline();
			let hsetnxCount = 0;

			for (let i = 0; i < existingStringIds.length; i++) {
				const stringId = existingStringIds[i];
				const originalId = existingIds[i];
				const name = nameResults[i];

				if (name && typeof name === 'string' && name.trim() !== '') {

					// INTELLIGENT RETRY LOGIC
					if (name.startsWith('RETRY:')) {
						const parts = name.split(':');
						const timestamp = parseInt(parts[1], 10);
						const timeElapsed = Date.now() - timestamp;

						if (timeElapsed > RETRY_COOLDOWN) {
							console.log(`[Check Cache] RETRY cooldown expired for ID ${originalId} (${Math.floor(timeElapsed/60000)}m elapsed). Re-queueing for ESI...`);
							missingIds.push(originalId);
						} else {
							// Still in cooldown period, treat as known failure for now
							cachedNames[originalId] = name;
						}
					} else {
						// This is a verified successful name resolution
						cachedNames[originalId] = name;

						// Ensure name_to_id reverse index is consistent (lowercase for search)
						nameToIdPipeline.hsetnx(NAME_TO_ID_HASH_KEY, name.toLowerCase(), String(originalId));
						hsetnxCount++;
					}
				} else {
					console.warn(`[Check Cache] ID ${stringId} existed in index but returned empty/invalid name. Forcing re-resolve.`);
					missingIds.push(originalId);
				}
			}

			// Execute consistency sync
			if (hsetnxCount > 0) {
				console.log(`[Check Cache] Syncing ${hsetnxCount} names to reverse search index...`);
				try {
					const syncResults = await nameToIdPipeline.exec();
					const actualSets = syncResults.filter(r => !r[0] && r[1] === 1).length;
					if (actualSets > 0) {
						console.log(`[Check Cache] Consistency Fix: Added ${actualSets} missing reverse-mappings.`);
					}
				} catch(execError) {
					console.error(`[Check Cache] Error during reverse-sync pipeline: ${execError.message}`);
				}
			}
		}
	} else {
		console.log('[Check Cache] No IDs provided for resolution in this batch.');
	}

	console.log(`[Check Cache] Final Batch Summary: ${Object.keys(cachedNames).length} resolved via Cache, ${missingIds.length} sent to ESI.`);

	// --- Return to Workflow ---
	return [{ json: {
		killmail_id_map: inputData.killmail_id_map,
		resolved_names: cachedNames,
		missing_ids: missingIds
	}}];

} catch (error) {
	console.error('❌ CRITICAL ERROR in Node 2 (Check Redis Cache):', error.message);
	console.error(error.stack);

	const inputData = $input.first() ? $input.first().json : {};
	// Safety Fallback: send all IDs to ESI if logic fails
	return [{ json: {
		killmail_id_map: inputData.killmail_id_map || {},
		resolved_names: {},
		missing_ids: inputData.all_ids_to_resolve || []
	}}];
} finally {
	if (redis) {
		await redis.quit();
	}
}

