/**
 * getBasicClass
 * Determines the broad category (e.g. Frigate, Structure) for a kill.
 * Logic: Overrides > Map Lookup > ID Range Fallbacks
 */
function getBasicClass(groupId, shipName = '') {
    const snL = (shipName || '').toLowerCase().trim();

    // 1. Name Overrides (Highest Priority)
    for (const [key, val] of Object.entries(SHIP_NAME_TO_CLASS_OVERRIDE)) {
        if (snL === key || snL.includes(key)) {
            return val;
        }
    }

    // 2. Map Lookup (Explicit IDs)
    if (SHIP_CLASS_BASIC_MAP[groupId]) {
        return SHIP_CLASS_BASIC_MAP[groupId];
    }

    // 3. String Matching Fallbacks (Safe guesses)
    if (snL.includes('standup')) return 'fighter';
    if (snL.includes('excavator')) return 'mining_haul';
    if (snL.includes('mobile warp disruptor')) return 'deployable';
    if (snL.includes('capsule')) return 'capsule';
    if (snL.includes('shuttle')) return 'shuttle';
    if (snL.includes('metenox')) return 'structure';
    if (snL.includes('skyhook')) return 'structure';
    if (snL.includes('control tower')) return 'control_tower';
    if (snL.includes('battery') || snL.includes('array') || snL.includes('assembly')) return 'starbase_structure';

    // 4. GroupID Ranges (Restoration Logic - LOW PRIORITY FALLBACK)
    if (groupId === 29) return 'capsule';
    if (groupId >= 1404 && groupId <= 2500) return 'structure'; 
    if (groupId >= 1000 && groupId <= 1399) return 'deployable';
    if (groupId >= 300 && groupId <= 500) return 'structure'; 

    return 'unknown';
}

