    // 1. Detailed Name Overrides (Check First)
    for (const [key, val] of Object.entries(SHIP_NAME_TO_DETAILED_CLASS_OVERRIDE)) {
        if (snL === key || snL.includes(key)) {
            return val;
        }
    }

    // 2. Basic Name Overrides (Fallback)
    if (SHIP_NAME_TO_CLASS_OVERRIDE[snL]) {
        return SHIP_NAME_TO_CLASS_OVERRIDE[snL];
    }

    // 3. String Match Traps (Safe overrides)
    if (snL.includes('mobile warp disruptor')) return 'mobile_warp_disruptor';
    if (snL.includes('mobile tractor unit')) return 'mobile_tractor_unit';
    if (snL.includes('mobile observatory')) return 'mobile_observatory';
    if (snL.includes('mercenary den')) return 'structure';
    if (snL.includes('skyhook')) return 'orbital_infrastructure';

    // 4. Faction Ship Detection (Navy/Pirate variants)
    if (snL.includes(' navy ') || snL.includes('navy issue')) {
        if (basicClass === 'frigate') return 'faction_frigate';
        if (basicClass === 'cruiser') return 'faction_cruiser';
        if (basicClass === 'battlecruiser') return 'faction_battlecruiser';
        if (basicClass === 'battleship') return 'faction_battleship';
    }
    const pirateFactions = ['angel', 'blood', 'guristas', 'mordus', 'sansha', 'serpentis', 'soct', 'kikimora', 'draugur', 'ikiheurs', 'leshak'];
    if (pirateFactions.some(faction => snL.includes(faction))) {
        if (basicClass === 'frigate') return 'faction_frigate';
        if (basicClass === 'cruiser') return 'faction_cruiser';
        if (basicClass === 'battlecruiser') return 'faction_battlecruiser';
        if (basicClass === 'battleship') return 'faction_battleship';
    }

    // 5. Map Lookup
    if (SHIP_CLASS_DETAILED_MAP[groupId]) {
        return SHIP_CLASS_DETAILED_MAP[groupId];
    }

    return basicClass;
}

/**
 * getSpaceType (v2.0 - Pochven Support)
 * Determines if a system is Highsec, Lowsec, Null, WH, Pochven, or Abyssal.
 * 
 * @param {number} security - System security status
 * @param {number} systemId - Solar system ID
 * @param {string} systemName - Solar system name
 * @param {number} regionId - Region ID (used for Pochven detection)
 * @returns {string} - Space type identifier
 */
function getSpaceType(security, systemId, systemName, regionId) {
    // 1. Abyssal Detection (system name starts with AD)
    if (systemName && systemName.startsWith('AD')) {
        return 'abyssal';
    }

    // 2. Wormhole Detection (J-space system ID range)
    if (systemId >= 31000000 && systemId < 32000000) {
        return 'wormhole';
    }

    // 3. Pochven Detection (region ID 10000070)
    if (regionId === POCHVEN_REGION_ID) {
        return 'pochven';
    }

    // 4. K-Space Security-based Classification
    if (Math.round(parseFloat(security) * 10) / 10 >= 0.5) {
        return 'highsec';
    }
    if (security > 0.0) {
        return 'lowsec';
    }

    return 'nullsec';
}

/**
 * isNPC (Strict Version)
 * Determines if an entity is an NPC based on IDs.
 */
function isNPC(charId, corpId, allianceId, factionId) {
    const cId = parseInt(charId || 0, 10);
    const coId = parseInt(corpId || 0, 10);

    if (cId === 0) return true; 
    if (coId === 1000133) return true; 
    if (cId >= 3000000 && cId <= 4000000) return true; 

    return false; 
}

function checkAbyssal(shipName, corpId) {
    if (shipName === 'Unstable Abyssal Depths' || parseInt(corpId) === 1000133) {
        return { 
            name: 'The Abyss', 
            corp: 'Environmental' 
        };
    }
    return null;
}

function getName(id, resolvedNames, def = 'Unknown') {
    const name = resolvedNames.get(parseInt(id));
    if (!name || name.startsWith('RETRY:')) {
        return `${def} (${id})`;
    }
    return name;
}

function getFleetSize(attackerCount) {
    if (attackerCount <= 1) return 'solo';
    if (attackerCount <= 5) return 'small';
    if (attackerCount <= 20) return 'medium';
    return 'large';
}

function getNPCDisplayName(characterId, shipTypeName, corporationId) {
    if (shipTypeName === 'Unstable Abyssal Depths' || parseInt(corporationId) === 1000133) {
        return 'The Abyss';
    }
    return 'NPC';
}

/**
 * estimateBlueprintValue
 * Complex valuation logic for BPO vs BPC.
 */
function estimateBlueprintValue(itemTypeId, singleton, quantity, groupId) {
    if (singleton === 0) return 0;

    let baseValue = 0;

    if (singleton === 1) { 
        if (groupId === 9) {
            if (itemTypeId >= 11567 && itemTypeId <= 12203) baseValue = 25000000000;
            else if (itemTypeId >= 23757 && itemTypeId <= 23919) baseValue = 150000000000;
            else if ([639, 643, 645, 647].includes(itemTypeId)) baseValue = 500000000;
            else if ([624, 626, 628].includes(itemTypeId)) baseValue = 200000000;
            else if ([11568, 11569, 11572, 11578].includes(itemTypeId)) baseValue = 30000000000;
            else if ([23913, 23915, 23917, 23919].includes(itemTypeId)) baseValue = 200000000000;
            else if ([23757, 23773, 23911, 23915].includes(itemTypeId)) baseValue = 100000000000;
            else baseValue = 50000000;
        } 
        else if ([10, 18].includes(groupId)) baseValue = 5000000;
        else if (groupId === 13) baseValue = 2000000;
        else baseValue = 10000000;
    } 
    else if (singleton === 2) { 
        baseValue = groupId === 9 ? 100000 : 1000000;
    }

    return baseValue * quantity;
}

// --- 5. INFRASTRUCTURE & REDIS ---

async function connectRedis() {
    console.log('[Indexer] Connecting to Redis...');
    for (let i = 0; i < MAX_RETRIES; i++) {
        try {
            const client = new Redis(REDIS_CONFIG);
            await new Promise((resolve, reject) => {
                client.on('ready', resolve);
                client.on('error', (err) => { client.quit(); reject(err); });
            });
            console.log(`[Indexer] Connected on attempt ${i + 1}`);
            return client;
        } catch (e) {
            console.warn(`[Indexer] Connection failed (Attempt ${i + 1}/${MAX_RETRIES})`);
            if (i === MAX_RETRIES - 1) throw e;
            await new Promise(r => setTimeout(r, 2000));
        }
    }
}

// --- 6. MAIN EXECUTION ---

return (async () => {
    let redisClient;
    const debugProcessedKills = [];
    const stats = {
        total: 0,
        bySpaceType: {},
        regionsFound: new Set(),
        regionNamesResolved: 0
    };

    try {
        const inputData = $input.first().json;
        if (!inputData?.killmail_id_map) {
            return [{ json: { error: 'No killmail map found', processed: 0 } }];
        }

        const kmMap = new Map(Object.entries(inputData.killmail_id_map));
        if (kmMap.size === 0) return [{ json: { processed: 0, message: 'Empty map' } }];

        console.log(`[Indexer] Processing batch of ${kmMap.size} killmails...`);

        const resolvedNamesMap = new Map(
            Object.entries(inputData.resolved_names || {}).map(([id, n]) => [parseInt(id), n])
        );

        redisClient = await connectRedis();
        const dataPipeline = redisClient.pipeline();
        const statsPipeline = redisClient.pipeline();

        // 6.1. BULK DATA PRE-FETCH
        const typeIds = new Set(), sysIds = new Set();
        for (const km of kmMap.values()) {
            sysIds.add(km.solar_system_id);
            if (km.victim?.ship_type_id) {
                typeIds.add(km.victim.ship_type_id);
            }
            if (km.victim?.items) {
                km.victim.items.forEach(i => typeIds.add(i.item_type_id));
            }
            if (km.attackers) {
                km.attackers.forEach(a => {
                    if (a.ship_type_id) typeIds.add(a.ship_type_id);
                });
            }
        }

        const sysIdsArray = Array.from(sysIds).map(String);
        const typeIdsArray = Array.from(typeIds).map(String);

        console.log(`[Indexer] Fetching data for ${sysIdsArray.length} systems, ${typeIdsArray.length} item types...`);

        const [sysRes, typeRes, priceRes] = await Promise.all([
            sysIdsArray.length > 0 ? redisClient.hmget('eve:system_details', ...sysIdsArray) : Promise.resolve([]),
            typeIdsArray.length > 0 ? redisClient.hmget('eve:item_classification', ...typeIdsArray) : Promise.resolve([]),
            typeIdsArray.length > 0 ? redisClient.hmget('eve:market:prices', ...typeIdsArray) : Promise.resolve([])
        ]);

        const systemMap = new Map(sysIdsArray.map((id, i) => [parseInt(id), sysRes[i] ? JSON.parse(sysRes[i]) : {}]));
        const groupMap = new Map(typeIdsArray.map((id, i) => [parseInt(id), typeRes[i] ? JSON.parse(typeRes[i]).groupID : 0]));
        const priceMap = new Map(typeIdsArray.map((id, i) => [parseInt(id), priceRes[i] ? (JSON.parse(priceRes[i]).average_price || 0) : 0]));

        // 6.1.1. COLLECT UNIQUE REGION IDs FOR NAME RESOLUTION
        const regionIds = new Set();
        for (const sys of systemMap.values()) {
            if (sys.regionID) {
                regionIds.add(sys.regionID);
            }
        }

        // 6.1.2. FETCH REGION NAMES
        const regionIdsArray = Array.from(regionIds).map(String);
        let regionNameMap = new Map();

        if (regionIdsArray.length > 0) {
            console.log(`[Indexer] Fetching names for ${regionIdsArray.length} unique regions...`);
            const regionNamesRaw = await redisClient.hmget('eve:id_to_name', ...regionIdsArray);

            regionIdsArray.forEach((id, i) => {
                const name = regionNamesRaw[i];
                if (name && !name.startsWith('RETRY:')) {
                    regionNameMap.set(parseInt(id), name);
                    stats.regionNamesResolved++;
                }
            });

            console.log(`[Indexer] Resolved ${stats.regionNamesResolved} region names`);
        }

        const itemClassificationMap = new Map();
        if (typeIds.size > 0) {
            const itemClassJson = await redisClient.hmget('eve:item_classification', ...Array.from(typeIds).map(String));
            Array.from(typeIds).forEach((id, i) => {
                if (itemClassJson[i]) {
                    itemClassificationMap.set(id, JSON.parse(itemClassJson[i]));
                }
            });
        }

        // 6.2. ENRICHMENT LOOP
        for (const [killIdStr, km] of kmMap.entries()) {
            const killId = parseInt(killIdStr);
            const zScore = Math.floor(new Date(km.killmail_time).getTime() / 1000);
            const enriched = { ...km };

            if (!enriched.zkb_hash && km?.package?.zkb?.hash) {
                enriched.zkb_hash = String(km.package.zkb.hash);
            }

            const v = enriched.victim;

            // --- Geographic Metadata (ENHANCED) ---
            const sys = systemMap.get(km.solar_system_id) || { security: 0 };
            enriched.solar_system_name = getName(km.solar_system_id, resolvedNamesMap, 'System');
            enriched.region_id = sys.regionID || null;
            enriched.constellation_id = sys.constellationID || null;

            // NEW: Add region_name to enriched kill
            if (enriched.region_id && regionNameMap.has(enriched.region_id)) {
                enriched.region_name = regionNameMap.get(enriched.region_id);
            } else {
                enriched.region_name = enriched.region_id ? `Region (${enriched.region_id})` : null;
            }

            // UPDATED: Pass regionId to getSpaceType for Pochven detection
            enriched.space_type = getSpaceType(sys.security, km.solar_system_id, enriched.solar_system_name, enriched.region_id);

            // Track stats
            stats.total++;
            stats.bySpaceType[enriched.space_type] = (stats.bySpaceType[enriched.space_type] || 0) + 1;
            if (enriched.region_id) stats.regionsFound.add(enriched.region_id);

            // --- Victim Metadata ---
            v.ship_type_name = getName(v.ship_type_id, resolvedNamesMap, 'Ship');
            v.is_npc = isNPC(v.character_id, v.corporation_id, v.alliance_id, v.faction_id);
            v.character_name = v.character_id ? getName(v.character_id, resolvedNamesMap) : (v.is_npc ? 'NPC' : 'Player Asset');
            v.corporation_name = getName(v.corporation_id, resolvedNamesMap, 'Corp');
            v.alliance_name = getName(v.alliance_id, resolvedNamesMap, 'None');

            // --- Attacker Metadata ---
            const playerAttackers = (enriched.attackers || []).filter(a => !isNPC(a.character_id, a.corporation_id, a.alliance_id, a.faction_id));
            enriched.is_solo = playerAttackers.length === 1;
            enriched.fleet_size = getFleetSize(playerAttackers.length);

            if (enriched.attackers) {
                enriched.attackers.forEach(a => {
                    a.ship_type_name = getName(a.ship_type_id, resolvedNamesMap, 'Ship');
                    a.is_npc = isNPC(a.character_id, a.corporation_id, a.alliance_id, a.faction_id);

                    const abyssCheck = checkAbyssal(a.ship_type_name, a.corporation_id);
                    if (abyssCheck) {
                        a.character_name = abyssCheck.name;
                        a.corporation_name = abyssCheck.corp;
                        a.is_npc = true;
                    } else if (a.is_npc) {
                        a.character_name = getNPCDisplayName(a.character_id, a.ship_type_name, a.corporation_id);
                        a.corporation_name = getName(a.corporation_id, resolvedNamesMap, 'Unknown Corp');
                    } else {
                        a.character_name = getName(a.character_id, resolvedNamesMap);
                        a.corporation_name = getName(a.corporation_id, resolvedNamesMap);
                    }

                    a.alliance_name = getName(a.alliance_id, resolvedNamesMap, 'None');
                    a.weapon_type_name = getName(a.weapon_type_id, resolvedNamesMap, 'Weapon');

                    const agId = groupMap.get(a.ship_type_id) || 0;
                    a.ship_class = getBasicClass(agId, a.ship_type_name);
                    a.ship_class_detailed = getDetailedClass(agId, a.ship_class, a.ship_type_name);
                });
            }

            // --- Dual Classification ---
            const gId = groupMap.get(v.ship_type_id) || 0;
            enriched.victim_ship_class = getBasicClass(gId, v.ship_type_name);
            enriched.victim_ship_class_detailed = getDetailedClass(gId, enriched.victim_ship_class, v.ship_type_name);

            // --- Value Calculation ---
            let shipVal = priceMap.get(v.ship_type_id) || 0;
            let destroyedVal = 0, droppedVal = 0;

            if (v.items) {
                v.items.forEach(i => {
                    i.item_type_name = getName(i.item_type_id, resolvedNamesMap, 'Item');
                    const qtyDes = i.quantity_destroyed || 0;
                    const qtyDrop = i.quantity_dropped || 0;
                    const totalQty = qtyDes + qtyDrop;

                    let itemVal = 0;
                    if (i.singleton > 0) {
                        const cls = itemClassificationMap.get(i.item_type_id);
                        itemVal = estimateBlueprintValue(i.item_type_id, i.singleton, totalQty, cls?.groupID || 0);
                    } else {
                        itemVal = (priceMap.get(i.item_type_id) || 0) * totalQty;
                    }

                    if (totalQty > 0) {
                        const ratio = qtyDes / totalQty;
                        destroyedVal += itemVal * ratio;
                        droppedVal += itemVal * (1 - ratio);
                    }
                });
            }

            enriched.ship_value = shipVal;
            enriched.destroyed_value = destroyedVal;
            enriched.dropped_value = droppedVal;
            enriched.total_value = shipVal + destroyedVal + droppedVal;

            // --- Time Metadata ---
            const killDate = new Date(km.killmail_time);
            enriched.kill_hour = killDate.getUTCHours();
            enriched.kill_day = killDate.getUTCDay();

            // 6.3. REDIS INDEXING

            // Core Data
            dataPipeline.hset('intel:kill:data', killIdStr, JSON.stringify(enriched));
            dataPipeline.zadd('intel:kills:all', zScore, killIdStr);
            dataPipeline.zadd('intel:kills:24h_stats', zScore, killIdStr);

            // Classes
            dataPipeline.zadd(`intel:losses:ship_class:${enriched.victim_ship_class}`, zScore, killIdStr);
            dataPipeline.zadd(`intel:losses:ship_class_detailed:${enriched.victim_ship_class_detailed}`, zScore, killIdStr);

            // ISK
            let valKey = 'sub10m';
            if (enriched.total_value >= 50e9) valKey = '50b';
            else if (enriched.total_value >= 20e9) valKey = '20b-50b';
            else if (enriched.total_value >= 10e9) valKey = '10b-20b';
            else if (enriched.total_value >= 1e9) valKey = '1b-10b';
            else if (enriched.total_value >= 100e6) valKey = '100m-1b';
            else if (enriched.total_value >= 10e6) valKey = '10m-100m';
            dataPipeline.zadd(`intel:kills:isk:${valKey}`, zScore, killIdStr);

            // Geo (INCLUDES POCHVEN NOW)
            dataPipeline.zadd(`intel:kills:space:${enriched.space_type}`, zScore, killIdStr);
            dataPipeline.zadd(`intel:kills:system:${km.solar_system_id}`, zScore, killIdStr);
            if (enriched.region_id) dataPipeline.zadd(`intel:kills:region:${enriched.region_id}`, zScore, killIdStr);
            if (enriched.constellation_id) dataPipeline.zadd(`intel:kills:constellation:${enriched.constellation_id}`, zScore, killIdStr);

            // Time & Fleet
            dataPipeline.zadd(`intel:kills:hour:${enriched.kill_hour}`, zScore, killIdStr);
            dataPipeline.zadd(`intel:kills:day:${enriched.kill_day}`, zScore, killIdStr);
            dataPipeline.zadd(`intel:kills:fleet:${enriched.fleet_size}`, zScore, killIdStr);

            // NPC & Weapon
            const fbAttacker = (enriched.attackers || []).find(a => a.final_blow);
            if (fbAttacker && fbAttacker.is_npc) {
                dataPipeline.zadd('intel:kills:npc', zScore, killIdStr);
            }
            if (fbAttacker && fbAttacker.weapon_type_id) {
                dataPipeline.zadd(`intel:kills:weapon:${fbAttacker.weapon_type_id}`, zScore, killIdStr);
            }

            // Tracking
            const involvedAids = new Set();
            if (v.alliance_id) involvedAids.add(v.alliance_id);
            (enriched.attackers || []).forEach(a => { if (a.alliance_id) involvedAids.add(a.alliance_id); });

            for (const aid of involvedAids) {
                dataPipeline.zadd(`intel:followed:alliance:${aid}`, zScore, killIdStr);
            }

            // VS/Brawl Mode: Alliance interaction tracking
            if (v.alliance_id) {
                const victimAllianceId = v.alliance_id;
                const attackerAllianceIds = new Set();
                (enriched.attackers || []).forEach(a => {
                    if (a.alliance_id && a.alliance_id !== victimAllianceId) {
                        attackerAllianceIds.add(a.alliance_id);
                    }
                });

                for (const attackerAid of attackerAllianceIds) {
                    dataPipeline.zadd(`intel:interaction:${attackerAid}:${victimAllianceId}`, zScore, killIdStr);
                    dataPipeline.zadd(`intel:interaction:${victimAllianceId}:${attackerAid}`, zScore, killIdStr);
                }
            }

            // Global Stats
            if (v.alliance_id) {
                dataPipeline.zadd(`intel:losses:alliance:${v.alliance_id}`, zScore, killIdStr);
                statsPipeline.hincrby(`${ALLIANCE_STATS_KEY}${v.alliance_id}`, 'loss_count_total', 1);
                statsPipeline.hincrbyfloat(`${ALLIANCE_STATS_KEY}${v.alliance_id}`, 'value_lost', enriched.total_value);
                dataPipeline.zadd(`intel:stats:alliance:losses_by_value:${v.alliance_id}`, enriched.total_value, killIdStr);
                statsPipeline.zadd(ALLIANCE_ACTIVITY_KEY, 'GT', zScore, v.alliance_id);
                if (v.character_id) statsPipeline.zadd(`${ALLIANCE_PILOTS_PREFIX}${v.alliance_id}`, 'GT', zScore, v.character_id);
                const victimGroupId = groupMap.get(v.ship_type_id) || 0;
                if (v.ship_type_name && v.ship_type_id && !EXCLUDED_TOP_SHIP_GROUPS.has(victimGroupId)) {
                    statsPipeline.zincrby(`${ALLIANCE_SHIPS_PREFIX}${v.alliance_id}`, 1, `${v.ship_type_id}:${v.ship_type_name}`);
                }
            }
            if (v.character_id && !v.is_npc) {
                dataPipeline.zadd(`intel:losses:character:${v.character_id}`, zScore, killIdStr);
            }
            if (v.corporation_id) {
                dataPipeline.zadd(`intel:losses:corporation:${v.corporation_id}`, zScore, killIdStr);
            }
            if (v.ship_type_id) {
                dataPipeline.zadd(`intel:losses:ship:${v.ship_type_id}`, zScore, killIdStr);
            }

            (enriched.attackers || []).forEach(a => {
                if (a.alliance_id) {
                    dataPipeline.zadd(`intel:kills:alliance:${a.alliance_id}`, zScore, killIdStr);
                    statsPipeline.hincrby(`${ALLIANCE_STATS_KEY}${a.alliance_id}`, 'kill_count_total', 1);
                    statsPipeline.hincrbyfloat(`${ALLIANCE_STATS_KEY}${a.alliance_id}`, 'value_destroyed', enriched.total_value / enriched.attackers.length);
                    dataPipeline.zadd(`intel:stats:alliance:kills_by_value:${a.alliance_id}`, enriched.total_value, killIdStr);
                    statsPipeline.zadd(ALLIANCE_ACTIVITY_KEY, 'GT', zScore, a.alliance_id);
                    if (a.character_id) statsPipeline.zadd(`${ALLIANCE_PILOTS_PREFIX}${a.alliance_id}`, 'GT', zScore, a.character_id);
                    const attackerGroupId = groupMap.get(a.ship_type_id) || 0;
                    if (a.ship_type_name && a.ship_type_id && !EXCLUDED_TOP_SHIP_GROUPS.has(attackerGroupId)) {
                        statsPipeline.zincrby(`${ALLIANCE_SHIPS_PREFIX}${a.alliance_id}`, 1, `${a.ship_type_id}:${a.ship_type_name}`);
                    }

                    if (a.final_blow) {
                        dataPipeline.zadd(`intel:kills:alliance:final:${a.alliance_id}`, zScore, killIdStr);
                        statsPipeline.hincrby(`${ALLIANCE_STATS_KEY}${a.alliance_id}`, 'kill_final_count', 1);
                    } else {
                        dataPipeline.zadd(`intel:kills:alliance:assist:${a.alliance_id}`, zScore, killIdStr);
                        statsPipeline.hincrby(`${ALLIANCE_STATS_KEY}${a.alliance_id}`, 'kill_assist_count', 1);
                    }
                }
                if (a.character_id && !a.is_npc) {
                    dataPipeline.zadd(`intel:kills:character:${a.character_id}`, zScore, killIdStr);
                    statsPipeline.hincrby(`${CHARACTER_STATS_KEY}${a.character_id}`, 'kill_count_total', 1);
                    statsPipeline.hincrbyfloat(`${CHARACTER_STATS_KEY}${a.character_id}`, 'value_destroyed', enriched.total_value / enriched.attackers.length);
                }
            });

            statsPipeline.hincrby(`${SYSTEM_STATS_KEY}${km.solar_system_id}`, 'kill_count_total', 1);
            statsPipeline.hincrbyfloat(`${SYSTEM_STATS_KEY}${km.solar_system_id}`, 'value_total', enriched.total_value);

            // Debug
            debugProcessedKills.push({
                id: killId,
                ship: v.ship_type_name,
                class: enriched.victim_ship_class,
                detailedClass: enriched.victim_ship_class_detailed,
                space_type: enriched.space_type,
                region_id: enriched.region_id,
                region_name: enriched.region_name,
                value: enriched.total_value
            });
        }

        console.log(`[Indexer] Executing Redis pipelines...`);
        await Promise.all([dataPipeline.exec(), statsPipeline.exec()]);

        // Summary - ONLY update alliances involved in this batch
        const batchAllianceIds = new Set();
        for (const [killIdStr, km] of kmMap.entries()) {
            const v = km.victim;
            if (v?.alliance_id) batchAllianceIds.add(v.alliance_id);
            (km.attackers || []).forEach(a => {
                if (a.alliance_id) batchAllianceIds.add(a.alliance_id);
            });
        }

        const activeAlliances = Array.from(batchAllianceIds).filter(id => id && id !== 0);

        if (activeAlliances.length === 0) {
            console.log('[Indexer] No alliances to update summaries for in this batch.');
        } else {
            console.log(`[Indexer] Updating summaries for ${activeAlliances.length} alliances from this batch.`);

            const sumPipe = redisClient.pipeline();
            const nowSec = Math.floor(Date.now() / 1000);
            const sevenDaysAgo = nowSec - (86400 * 7);

            for (const aid of activeAlliances) {
                const allianceStats = await redisClient.hmget(`${ALLIANCE_STATS_KEY}${aid}`,
                    'kill_count_total', 'loss_count_total', 'value_destroyed', 'value_lost',
                    'kill_final_count', 'kill_assist_count');
                const lastSeenScore = await redisClient.zscore(ALLIANCE_ACTIVITY_KEY, aid);
                const pilotsKey = `${ALLIANCE_PILOTS_PREFIX}${aid}`;
                await redisClient.zremrangebyscore(pilotsKey, '-inf', sevenDaysAgo);
                const activePilots = await redisClient.zcard(pilotsKey);
                const shipsKey = `${ALLIANCE_SHIPS_PREFIX}${aid}`;
                const topShipsRaw = await redisClient.zrevrange(shipsKey, 0, 0);

                let topShipName = '-';
                let topShipId = '';
                if (topShipsRaw[0]) {
                    const colonIdx = topShipsRaw[0].indexOf(':');
                    if (colonIdx > 0) {
                        topShipId = topShipsRaw[0].substring(0, colonIdx);
                        topShipName = topShipsRaw[0].substring(colonIdx + 1);
                    } else {
                        topShipName = topShipsRaw[0];
                    }
                }

                const maxKillIds = await redisClient.zrevrange(`intel:stats:alliance:kills_by_value:${aid}`, 0, 0);
                const maxLossIds = await redisClient.zrevrange(`intel:stats:alliance:losses_by_value:${aid}`, 0, 0);

                const [k, l, vd, vl, kf, ka] = allianceStats.map(Number);
                const efficiency = (vd + vl) > 0 ? (vd / (vd + vl) * 100) : 0;
                const ratio = l > 0 ? (k / l) : k;

                sumPipe.hset(`${ALLIANCE_SUMMARY_KEY}${aid}`,
                    'kills', k || 0,
                    'losses', l || 0,
                    'iskDestroyed', (vd || 0).toFixed(0),
                    'iskLost', (vl || 0).toFixed(0),
                    'efficiency', efficiency.toFixed(1),
                    'ratio', ratio.toFixed(2),
                    'activePilots', activePilots || 0,
                    'lastSeen', lastSeenScore ? (lastSeenScore * 1000) : 0,
                    'topShip', topShipName,
                    'topShipId', topShipId,
                    'maxKillId', maxKillIds[0] || '',
                    'maxLossId', maxLossIds[0] || '',
                    'killsFinal', kf || 0,
                    'killsAssist', ka || 0
                );
            }
            await sumPipe.exec();
        }

        // Final logging
        console.log(`[Indexer] ========== BATCH COMPLETE ==========`);
        console.log(`[Indexer] Total Kills Processed: ${stats.total}`);
        console.log(`[Indexer] Space Type Breakdown:`);
        for (const [spaceType, count] of Object.entries(stats.bySpaceType)) {
            console.log(`[Indexer]   - ${spaceType}: ${count}`);
        }
        console.log(`[Indexer] Unique Regions: ${stats.regionsFound.size}`);
        console.log(`[Indexer] Region Names Resolved: ${stats.regionNamesResolved}`);
        console.log(`[Indexer] ======================================`);

        return [{ json: { 
            processed: kmMap.size, 
            status: 'success',
            stats: {
                total: stats.total,
                bySpaceType: stats.bySpaceType,
                uniqueRegions: stats.regionsFound.size,
                regionNamesResolved: stats.regionNamesResolved
            },
            debug_kills: debugProcessedKills 
        }}];

    } catch (err) {
        console.error(`[Indexer] CRITICAL ERROR: ${err.message}`);
        console.error(err.stack);
        return [{ json: { 
            status: 'error',
            message: err.message,
            stack: err.stack,
            debug_kills: debugProcessedKills 
        }}];
    } finally {
        if (redisClient) await redisClient.quit();
    }
})();

/**
 * Node 4: Merge and Cache Names
 * Version: 1.8 (Enhanced Resolution & Negative Caching Logic)
 * * This node performs three critical functions:
 * 1. Merges names found in the local Redis cache with new results from ESI.
 * 2. Implements "Negative Caching" by tagging failed ESI lookups with a 
 * RETRY prefix and timestamp to prevent immediate API spamming.
 * 3. Updates the persistent ESI Name Cache in Redis (both directions).
 */

const Redis = require('ioredis');
let redis; 

try {
    const items = $input.all();

    // --- 1. INITIALIZATION & INPUT VALIDATION ---
    if (!items || items.length === 0) {
        console.warn('[Resolve IDs] No input items detected. Skipping process.');
        return [{ json: { killmail_id_map: {}, resolved_names: {}, resolution_stats: { status: 'empty_input' } } }];
    }

    let killmailMap = {};
    let existingResolvedNames = {}; // Provided by Node 2 (Cache Check)
    const newResolvedNames = {};    // Provided by Node 3 (ESI Fetch)
    let expectedMissingIds = [];    // IDs that we attempted to fetch from ESI

    console.log(`[Resolve IDs] Sorting and validating ${items.length} input segments...`);

    // --- 2. INPUT DATA AGGREGATION ---
    for (const item of items) {
        const json = item.json;

        // Check for the main state package (Killmail map and missing ID list)
        if (json && json.killmail_id_map) {
            killmailMap = json.killmail_id_map;
            existingResolvedNames = json.resolved_names || {};
            if (Array.isArray(json.missing_ids)) {
                expectedMissingIds = json.missing_ids;
            }
        } 
        // Check for ESI response arrays
        else if (Array.isArray(json) && json.length > 0 && json[0].id) {
            json.forEach(entry => {
                if (entry.id && entry.name) {
                    newResolvedNames[entry.id] = entry.name;
                }
            });
        }
        // Check for individual ESI objects (fallback for specific batching configurations)
        else if (json && json.id && json.name) {
            newResolvedNames[json.id] = json.name;
        }
    }

    const totalKillmails = Object.keys(killmailMap).length;
    if (totalKillmails === 0) {
        console.warn('[Resolve IDs] Killmail map is empty. No further indexing required.');
        return [{ json: { killmail_id_map: {}, resolved_names: {}, resolution_stats: { status: 'no_killmails' } } }];
    }

    // --- 3. NEGATIVE CACHE LOGIC (RETRY SYSTEM) ---
    const now = Date.now();
    let failedLookupCount = 0;

    console.log(`[Resolve IDs] Processing ESI results: ${Object.keys(newResolvedNames).length} resolved, ${expectedMissingIds.length} expected.`);

    for (const id of expectedMissingIds) {
        const numericId = parseInt(id, 10);

        if (!newResolvedNames[numericId]) {
            /**
             * If ESI failed to resolve the ID, we cache a temporary RETRY status.
             * Node 2 will see this and block re-attempts for 4 hours.
             */
            const retryStatus = `RETRY:${now}:${numericId}`;
            newResolvedNames[numericId] = retryStatus;
            failedLookupCount++;
        }
    }

    // Merge everything into the final map for the indexer (Node 5)
    const finalResolvedNames = { ...existingResolvedNames, ...newResolvedNames };

    // --- 4. PERSISTENCE LAYER (REDIS) ---
    const namesToCacheCount = Object.keys(newResolvedNames).length;

    if (namesToCacheCount > 0) {
        console.log(`[Resolve IDs] Connecting to Redis to update ${namesToCacheCount} name records...`);

        redis = new Redis({ 
            host: 'redis', 
            port: 6379, 
            db: 0, 
            connectTimeout: 5000,
            maxRetriesPerRequest: 3
        });

        // Wait for connection readiness
        await new Promise((resolve, reject) => {
            redis.on('ready', resolve);
            redis.on('error', (err) => {
                console.error('[Resolve IDs] Redis connection failed:', err.message);
                reject(err);
            });
            setTimeout(() => reject(new Error('Redis connection timeout')), 6000);
        });

        const pipeline = redis.pipeline();
        let commandCount = 0;
        let successfulCacheCount = 0;
        let retryCacheCount = 0;

        for (const id in newResolvedNames) {
            const nameValue = newResolvedNames[id];
            if (!nameValue || !id) continue;

            const stringId = String(id);

            // Update the primary ID -> NAME mapping
            pipeline.hset('eve:id_to_name', stringId, nameValue);
            commandCount++;

            // Only update the NAME -> ID (search index) if it's a real name
            if (!nameValue.startsWith('RETRY:')) {
                pipeline.hset('eve:name_to_id', nameValue.toLowerCase(), stringId);
                commandCount++;
                successfulCacheCount++;
            } else {
                retryCacheCount++;
            }
        }

        if (commandCount > 0) {
            console.log(`[Resolve IDs] Executing pipeline (${commandCount} commands)...`);
            const results = await pipeline.exec();

            // Validate individual pipeline results
            let errorCount = 0;
            results.forEach((res, index) => {
                if (res[0]) {
                    console.error(`[Resolve IDs] Pipeline error at index ${index}:`, res[0]);
                    errorCount++;
                }
            });

            if (errorCount === 0) {
                console.log(`[Resolve IDs] ✅ Successfully cached ${successfulCacheCount} names and ${retryCacheCount} retry states.`);
            } else {
                console.warn(`[Resolve IDs] ⚠️ Processed with ${errorCount} individual command errors.`);
            }
        }
    } else {
        console.log('[Resolve IDs] No new ESI data to cache in this cycle.');
    }

    // --- 5. PERFORMANCE METRICS & FINAL OUTPUT ---
    const resolutionStats = {
        total_killmails: totalKillmails,
        from_cache: Object.keys(existingResolvedNames).length,
        from_esi_success: Object.keys(newResolvedNames).filter(id => !newResolvedNames[id].startsWith('RETRY:')).length,
        from_esi_failed: failedLookupCount,
        total_in_map: Object.keys(finalResolvedNames).length,
        timestamp: new Date().toISOString()
    };

    console.log('[Resolve IDs] Ingestion Summary:');
    console.log(`  - Total Entities: ${resolutionStats.total_in_map}`);
    console.log(`  - Cache Hits:     ${resolutionStats.from_cache}`);
    console.log(`  - ESI Resolves:   ${resolutionStats.from_esi_success}`);
    console.log(`  - Negative Cache: ${resolutionStats.from_esi_failed}`);

    // Standardized return for the indexer
    return [{ json: { 
        killmail_id_map: killmailMap, 
        resolved_names: finalResolvedNames,
        resolution_stats: resolutionStats
    }}];

} catch (error) {
    console.error('[Resolve IDs] ❌ CRITICAL ERROR:', error.message);
    console.error(error.stack);

    // In case of failure, try to pass the data through with empty names to avoid breaking the workflow
    const rawItems = $input.all();
    let fallbackMap = {};
    for (const item of rawItems) {
        if (item.json?.killmail_id_map) fallbackMap = item.json.killmail_id_map;
    }

    return [{ json: { 
        error: error.message,
        killmail_id_map: fallbackMap, 
        resolved_names: {},
        resolution_stats: { status: 'critical_error' }
    }}];

} finally {
    // Ensure cleanup of the database connection
    if (redis && redis.status === 'ready') {
        try {
            await redis.quit();
            console.log('[Resolve IDs] Redis connection closed gracefully.');
        } catch (quitErr) {
            console.error('[Resolve IDs] Error closing Redis:', quitErr.message);
        }
    }
}

