// Node: Deduplicate Batch
// Purpose: Checks batch against intel:kill:data. Only passes on new kills.

const Redis = require('ioredis');
let redis;

// The hash your "5. Redis Processing" node writes to
const PROCESSED_HASH_KEY = 'intel:kill:data'; 

try {
    const items = $input.all();
    if (items.length === 0) {
        console.log('[Dedupe] No items in batch. Stopping.');
        return []; // Stop the workflow run
    }

    // Extract the killmail_id from the specific input structure
    // The input comes from "Get Batch & Set Heartbeat"
    const killIdsToCheck = items.map(item => String(item.json.package.killmail.killmail_id));

    redis = new Redis({ host: 'redis', port: 6379, db: 0, connectTimeout: 5000 });

    // Use HEXISTS in a pipeline for a super-fast bulk check
    const checkPipeline = redis.pipeline();
    killIdsToCheck.forEach(id => {
        checkPipeline.hexists(PROCESSED_HASH_KEY, id);
    });
    const existsResults = await checkPipeline.exec();

    const newKills = []; // This will hold only new kills
    let duplicateCount = 0;

    for (let i = 0; i < items.length; i++) {
        // existsResults[i] is [error, result]
        // result is 0 if it does NOT exist, 1 if it does
        const doesExist = existsResults[i][1] === 1;

        if (!doesExist) {
            newKills.push(items[i]); // Pass the original item through
        } else {
            duplicateCount++;
        }
    }

    if (duplicateCount > 0) {
        console.log(`[Dedupe] Dropped ${duplicateCount} duplicate kills from this batch.`);
    }

    if (newKills.length === 0) {
        console.log('[Dedupe] All kills in batch were duplicates. Stopping.');
        return []; // Stop the workflow run
    }

    console.log(`[Dedupe] Passing ${newKills.length} new kills to processor.`);
    return newKills;

} catch (error) {
    console.error('❌ CRITICAL ERROR in Deduplicate Batch:', error.message, error.stack);
    throw new Error('Deduplicate Batch failed: ' + error.message);
} finally {
    if (redis) {
        await redis.quit();
        console.log('[Dedupe] Redis connection closed.');
    }
}
